import argparse,base64,hashlib,json,os
ap=argparse.ArgumentParser();ap.add_argument('base',type=Path);ap.add_argument('--credential-file',type=Path,required=True);a=ap.parse_args();base=a.base.resolve();out=base/'observability';os.environ['WANDB_API_KEY']=a.credential_file.read_text().strip();os.environ['WANDB_SILENT']='true';os.environ['WANDB_CONSOLE']='off'
