m=json.loads((base/'accepted-best/handoff.json').read_text());assert m['accepted'];rid='medium-handoff-'+m['board_sha256'][:12];run=wandb.init(entity='philippe-fdesousa',project='copper-scar',id=rid,name='medium-loop · accepted handoff',job_type='immutable-handoff-publication',dir=str(out),config={'size_family':'medium-loop','optimization_stage':'stage-one-feasibility','handoff':m});artifact=wandb.Artifact('medium-loop-accepted-best',type='native-board-evidence',metadata={'board_sha256':m['board_sha256'],'size_family':'medium-loop','native_accepted':True});artifact.add_dir(str(base/'accepted-best'),name='accepted-best');artifact.add_dir(str(base/'replay'),name='replay');run.log_artifact(artifact);run.summary.update({'accepted':True,'native_opens':0,'native_drc_violations':0,'native_schematic_parity_issues':0,'native_erc_violations':0,'wire_length_mm':m['evaluation']['wire_length_mm'],'vias':m['evaluation']['vias'],'models':85,'stage_two_score_computed':False});url=run.url;run.finish();api=wandb.Api();remote=api.artifact('philippe-fdesousa/copper-scar/'+artifact.name+':latest');key='accepted-best/pcbgolf.kicad_pcb';digest=base64.b64encode(hashlib.md5((base/key).read_bytes()).digest()).decode();assert remote.manifest.entries[key].digest==digest;assert remote.metadata['board_sha256']==m['board_sha256'];receipt={'run_url':url,'artifact':remote.qualified_name,'board_sha256':m['board_sha256'],'remote_board_digest_verified':True,'file_count':len(remote.manifest.entries)};(out/'handoff-verified.json').write_text(json.dumps(receipt,indent=2));print(json.dumps(receipt))
